import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.kOe0DhAP.js";const _=JSON.parse('{"title":"核心设计","description":"把订单、持仓、保证金和风险状态分开建模。","frontmatter":{"title":"核心设计","description":"把订单、持仓、保证金和风险状态分开建模。"},"headers":[],"relativePath":"07/0703/070003.md","filePath":"07/0703/070003.md"}'),i={name:"07/0703/070003.md"};function s(n,a,d,l,c,h){return r(),t("div",null,[...a[0]||(a[0]=[o('<div class="doc-eyebrow">合约手册 / TGEX KNOWLEDGE BASE</div><h1 id="核心设计" tabindex="-1">核心设计 <a class="header-anchor" href="#核心设计" aria-label="Permalink to &quot;核心设计&quot;">​</a></h1><div class="doc-lead">把订单、持仓、保证金和风险状态分开建模。</div><h2 id="position" tabindex="-1">账户与持仓 <a class="header-anchor" href="#position" aria-label="Permalink to &quot;账户与持仓 {#position}&quot;">​</a></h2><p>订单表达待执行意图，持仓表达已成交敞口。持仓通常需要方向、数量、开仓均价、可平数量和相关保证金。撤销未成交的开仓订单不等于平掉已经建立的持仓。</p><h2 id="orders" tabindex="-1">订单状态 <a class="header-anchor" href="#orders" aria-label="Permalink to &quot;订单状态 {#orders}&quot;">​</a></h2><p>订单状态反映受理、成交和终止结果；持仓状态反映有效敞口和关闭过程。二者不能共用一套状态含义，强平过程也需要关联具体持仓和清算记录。</p><h2 id="pnl" tabindex="-1">保证金与盈亏 <a class="header-anchor" href="#pnl" aria-label="Permalink to &quot;保证金与盈亏 {#pnl}&quot;">​</a></h2><p>线性合约的简化多仓浮盈 = 数量 ×（参考价格 − 开仓均价）；空仓方向相反。合约乘数、结算币、手续费和资金费会影响实际权益。本公式仅用于说明方向关系。</p><h2 id="risk" tabindex="-1">风险与强平 <a class="header-anchor" href="#risk" aria-label="Permalink to &quot;风险与强平 {#risk}&quot;">​</a></h2><p>风险计算需要稳定的价格与资产口径。权益低于对应维持要求时触发怎样的处理，应由产品规则和风险引擎决定；不能仅用“亏完初始保证金”作为所有产品的强平条件。</p>',11)])])}const u=e(i,[["render",s]]);export{_ as __pageData,u as default};
